def html_page(slug, title, desc, audience, bullets, points, faqs, is_hub=False):
    url = f"{BASE}/seo-guides/{slug}/"
    faq_html = ''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in zip(faqs[::2], faqs[1::2]))
    cards = ''.join(f'<article class="card"><h3>{escape(b)}</h3><p>{escape(p)}</p></article>' for b,p in zip(bullets, points))
    steps = ''.join(f'<article class="step"><b>{i:02d}</b><h3>{escape(x)}</h3><p>{escape(y)}</p></article>' for i,(x,y) in enumerate(zip(["افهم المتطلبات","نظّم الفكرة","تحقق قبل التسليم"], points),1))
    if is_hub:
        cards = ''.join(f'<article class="card"><h3><a href="/seo-guides/{s}/">{escape(t)}</a></h3><p>{escape(d)}</p></article>' for s,t,d,*_ in pages)
        desc = "دليل الباحث من أورا للأفكار: صفحات عملية حول الخطط البحثية والرسائل الجامعية والتحليل والتوثيق والمشاريع في الكويت والإمارات."
        title = "دليل الباحث الجامعي في الكويت والإمارات | أورا للأفكار"
        url = f"{BASE}/seo-guides/"
        audience = "طلاب الجامعات والدراسات العليا والباحثون في الكويت والإمارات"
        bullets = ["خطط البحث والمنهجيات", "الرسائل الجامعية والتحليل", "التوثيق والتدقيق والعروض"]
        points = ["محتوى إرشادي قابل للتطبيق", "روابط إلى خدمات أورا ذات الصلة", "دعم يحافظ على أصالة الباحث"]
        faq_html = '<details><summary>هل هذه الصفحات بديل عن تعليمات الجامعة؟</summary><p>لا. هي إرشادات عامة، ويجب دائمًا الرجوع إلى دليل الجامعة والمشرف ومتطلبات المقرر.</p></details><details><summary>هل تنفذ أورا البحث أو الرسالة بالنيابة عن الطالب؟</summary><p>لا. يقتصر الدعم على الإرشاد والتدريب والمراجعة والتدقيق والتنسيق بما يحافظ على مسؤولية الباحث عن عمله.</p></details>'
        steps = ''.join(f'<article class="step"><b>{i:02d}</b><h3>{escape(x)}</h3><p>{escape(y)}</p></article>' for i,(x,y) in enumerate(zip(bullets, points),1))
    graph = {"@context":"https://schema.org","@type":"WebPage","name":title,"url":url,"inLanguage":"ar","isPartOf":{"@type":"WebSite","url":BASE+"/"}}
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title if title.endswith('أورا للأفكار') else title + ' | أورا للأفكار')}</title><meta name="description" content="{escape(desc)}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{url}"><meta property="og:site_name" content="أورا للأفكار"><meta property="og:image" content="{BASE}/logo-512.png"><meta name="twitter:card" content="summary_large_image"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><script type="application/ld+json">{json.dumps(graph,ensure_ascii=False)}</script><style>{CSS}</style></head><body><header class="hero"><div class="wrap"><div class="brand"><a href="{BASE}/" style="text-decoration:none">أورا <span>للأفكار</span></a></div><span class="badge">دليل الباحث • محتوى إرشادي مستقل</span><h1>{escape(title)}</h1><p class="lead">{escape(desc)}</p><div class="actions"><a class="button primary" href="{BASE}/contact/">تواصل مع أورا</a><a class="button outline" href="{BASE}/seo-guides/">استعرض دليل الباحث</a></div></div></header><main><section class="section"><div class="wrap"><p class="kicker">لمن هذا الدليل؟</p><h2 class="heading">{escape(audience)}</h2><p class="intro">تساعدك هذه الصفحة على تنظيم العمل وفهم القرارات البحثية. استخدمها كنقطة بداية، ثم طابق خطواتك مع تعليمات الجامعة والمشرف والتخصص.</p><div class="grid">{cards}</div></div></section><section class="section soft"><div class="wrap"><p class="kicker">منهج عملي</p><h2 class="heading">ثلاث نقاط تساعدك على التقدم</h2><div class="steps">{steps}</div></div></section><section class="section"><div class="wrap"><p class="kicker">أسئلة شائعة</p><h2 class="heading">أسئلة يحتاجها الباحث قبل البدء</h2><div>{faq_html}</div></div></section><section class="section cta"><div class="wrap"><p class="kicker">دعم مسؤول</p><h2 class="heading">هل تحتاج إلى مراجعة احتياجك البحثي؟</h2><p class="intro">يمكن لفريق أورا مناقشة المرحلة التي وصلت إليها وتحديد نطاق الإرشاد أو المراجعة المناسب، مع بقاء القرارات والمحتوى العلمي مسؤولية الباحث.</p><div class="actions" style="justify-content:center"><a class="button primary" href="{WA}" target="_blank" rel="noopener noreferrer">اطلب استشارة أولية</a><a class="button" style="border:1px solid var(--teal);color:var(--teal)" href="{BASE}/خدماتنا/">تعرف على الخدمات</a></div></div></section></main><footer class="footer">أورا للأفكار | <a href="{BASE}/">الرئيسية</a> · <a href="{BASE}/contact/">تواصل معنا</a> · <a href="{BASE}/privacy-policy/">الخصوصية</a><br>المحتوى إرشادي، ولا يُقدَّم لتنفيذ بحث أو رسالة بالنيابة عن الباحث.</footer></body></html>'''

